// Demo: Signature Posted Write Semantics — posted vs non-posted ordering
var log=[];
function posted(w){log.push('posted:'+w);}
function nonposted(w){log.push('nonposted:'+w+' (acked)');}
posted('A');posted('B');nonposted('C');
console.log('technique: Signature Posted Write Semantics');console.log(log.join(' -> '));
console.log('non-posted C acts as a barrier: A,B are visible before C completes');

// Demo: Signature Read-Modify-Write Safety — doorbell batching
var regs=30,per=50;
var single=regs*per,batched=per+regs*2;
console.log('technique: Signature Read-Modify-Write Safety');console.log('registers: '+regs);
console.log('individual MMIO: '+single+' ns, batched doorbell: '+batched+' ns');
console.log('batching saves '+Math.round(100*(1-batched/single))+'% of MMIO cost');

